INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5478690, 788723, 83313, '<td valign="top">I like the appearance of the yellow steps, but it comes a little short of having strong impact on me. Maybe its the overall composition, but I''m not sure.</td>', 'I like the appearance of the yellow steps, but it comes a little short of having strong impact on me. Maybe its the overall composition, but I''m not sure.', '2009-05-09 22:32:47.000000', NULL, 1),
(5478889, 788354, 31637, '<td valign="top">Not an easy shot to take handheld, this is effective technically.</td>', 'Not an easy shot to take handheld, this is effective technically.', '2009-05-10 01:52:26.000000', NULL, 1),
(5478895, 788671, 31637, '<td valign="top">Crazyy...curious image, 6</td>', 'Crazyy...curious image, 6', '2009-05-10 01:55:38.000000', NULL, 1),
(5478896, 788659, 31637, '<td valign="top">Nice place</td>', 'Nice place', '2009-05-10 01:56:06.000000', NULL, 1),
(5478898, 787205, 31637, '<td valign="top">Nice B/W, perfectly done. A very interesting crop.</td>', 'Nice B/W, perfectly done. A very interesting crop.', '2009-05-10 01:57:03.000000', NULL, 1),
(5478955, 788161, 31637, '<td valign="top">This is a lovely use of natural light, and great framing. Too bad there isn''t any added drama with a central subject like a person.</td>', 'This is a lovely use of natural light, and great framing. Too bad there isn''t any added drama with a central subject like a person.', '2009-05-10 03:42:31.000000', NULL, 1),
(5478957, 787304, 31637, '<td valign="top">Great color and tones.</td>', 'Great color and tones.', '2009-05-10 03:42:47.000000', NULL, 1),
(5478958, 788768, 31637, '<td valign="top">Spectacular image, I can''t imagine how this is done.</td>', 'Spectacular image, I can''t imagine how this is done.', '2009-05-10 03:43:13.000000', NULL, 1),
(5478973, 787082, 70000, '<td valign="top">The ring light reflecting in the cat''s eyes is a perfect compliment to the hint of it in the giant sunglasses. Very fun!</td>', 'The ring light reflecting in the cat''s eyes is a perfect compliment to the hint of it in the giant sunglasses. Very fun!', '2009-05-10 04:30:49.000000', NULL, 1),
(5478976, 787701, 70000, '<td valign="top">I wish it wasn''t so obvious this was a photographic umbrella. I love the colors and the side light. Very nice. If you had more freedom with the editing I would love to see the support lines on the umbrella lightened or something. Still, very well thought out shot.</td>', 'I wish it wasn''t so obvious this was a photographic umbrella. I love the colors and the side light. Very nice. If you had more freedom with the editing I would love to see the support lines on the umbrella lightened or something. Still, very well thought out shot.', '2009-05-10 04:32:28.000000', NULL, 1),
(5478991, 788671, 102925, '<td valign="top">This is why I come here. To see how far people can take the topic and push the boundaries with it. What an awesome, random, yet topically-correct concept.<br/> <br/>My only criticism would be that the object to the right of the banana detracts a little from the otherwise ethereal effect.<br/> <br/>It mightn''t be the prettiest, but to me it''s one of the best.<br/>But great thinking. 8 :)</td>', 'This is why I come here. To see how far people can take the topic and push the boundaries with it. What an awesome, random, yet topically-correct concept. My only criticism would be that the object to the right of the banana detracts a little from the otherwise ethereal effect. It mightn''t be the prettiest, but to me it''s one of the best.But great thinking. 8 :)', '2009-05-10 05:21:13.000000', NULL, 1),
